import { LunarWorld } from './ruins-world.js';
import {Race,ROUTES,SPEED} from './engine.js';
const params=new URLSearchParams(location.search),qa=params.get('qa')==='1';
if(params.has('floor')){location.replace('sandbox.html?floor=1');}else{
const fixedOutcome=qa&&['stable','collapse'].includes(params.get('outcome'))?params.get('outcome'):null;
const $=s=>document.querySelector(s),canvas=$('#map'),race=new Race(fixedOutcome?{random:()=>fixedOutcome==='collapse'?.1:.9}:undefined);
const world=new LunarWorld(canvas);
const colors=['#70d4f6','#edc871'],routeName={beacon:'信标回廊',outer:'废弃栈道',safe:'归航环路',risk:'碎隙捷径'};
let demo=false,last=performance.now(),uiLast='',lastEvent='',eventAt=0,sound=false,audio=null;
if(qa){document.body.classList.add('qa');const badge=document.createElement('div');badge.className='qa-badge';badge.textContent='工程验证 · '+(fixedOutcome||'随机')+' / 手动时钟';document.body.append(badge);}
world.ready.then(()=>{uiLast='';renderUI();}).catch(()=>{$('#startBtn').disabled=true;});
function render(){world.update(race);}
function beep(){if(!sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(540,audio.currentTime);o.frequency.exponentialRampToValueAtTime(260,audio.currentTime+.12);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.2);}catch{}}
function renderUI(){const selecting=race.quake!==null&&!race.locked&&race.status==='running';const signature=JSON.stringify([world.loaded,race.status,race.paused,race.players.map(p=>[p.opening,p.finalChoice,p.final,p.card,!!race.legal(p.id),p.beacon,p.gate]),race.quake,race.locked,race.aftershock]);
 $('#timer').innerHTML=`${String(Math.floor(race.time/60)).padStart(2,'0')}:${String(Math.floor(race.time%60)).padStart(2,'0')}<span>.${Math.floor(race.time*10)%10}</span>`;
 $('#phase').textContent=race.status==='finished'?'撤离完成':race.paused?'任务暂停':selecting?'月震 · 秘密选路':race.status==='ready'?'等待发车':race.locked?'末段撤离':'实时竞速';
 $('#phaseDetail').textContent=selecting?`剩余 ${Math.max(0,7-(race.time-race.quake)).toFixed(1)} 秒` :race.status==='ready'?'双方选路后即可开始':race.aftershock==='collapse'?'共享余震：前方塌陷':race.aftershock==='stable'?'共享余震：道路稳定':race.locked?'末段路线已锁定':'双车独立车道 · 位置触发';
 if(signature!==uiLast){uiLast=signature;$('#quakeBtn').disabled=race.status==='running';
 for(const p of race.players){const finalStage=race.quake!==null;const options=finalStage?['risk','safe']:['beacon','outer'];const canChoose=race.status==='ready'||selecting;const submitted=canChoose&&(finalStage?p.finalChoice:p.opening);const selected=finalStage?p.final:p.opening;
 $(`#player${p.id}`).innerHTML=`<div class="player-title"><b>${p.id===0?'蓝方':'黄方'} <small>ROVER 0${p.id+1}</small></b><span>${submitted?'已提交 · 等待公开':p.beacon?'信标已激活':'就绪'}</span></div><div class="route-buttons">${options.map((r,i)=>`<button class="route-btn ${!canChoose&&selected===r?'selected':''}" data-route="${r}" data-player="${p.id}" ${!canChoose||race.paused?'disabled':''}><b>${r==='beacon'?'◈':r==='outer'?'⌁':r==='risk'?'ϟ':'◎'} ${routeName[r]}</b><span>${r==='beacon'?'更快 / 绕行代价高':r==='outer'?'稳健 / 抗落石干扰':r==='risk'?'冒险 / 50% 共享塌陷':'稳定 / 约 20 秒'} · ${p.id===0?i+1:i+8}</span></button>`).join('')}</div><div class="rock-row"><span class="mini-card card-front" aria-hidden="true"></span><button class="rock-btn" data-attack="${p.id}" ${!race.legal(p.id)?'disabled':''}>☄ ${p.card?'投放落石':'落石已用'} <small>${p.id===0?'Q':'P'}</small></button><span class="rock-hint">${!p.card?'本局 0 / 1':race.legal(p.id)?'可使用 · 已锁定对手前方落点':'暂无合法落点 · 卡牌保留'}</span></div>`;}
 $('#startBtn').disabled=!world.loaded||race.status!=='ready'||race.players.some(p=>!p.opening);$('#startBtn').innerHTML=race.status==='ready'?(race.players.every(p=>p.opening)?'同时翻牌 · 开始撤离 <span>→</span>':'双方选路后发车 <span>→</span>'):race.status==='finished'?'任务完成':'撤离进行中';$('#pauseBtn').disabled=race.status!=='running';$('#pauseBtn').textContent=race.paused?'▷ 继续':'Ⅱ 暂停';$('#demoBtn').disabled=race.status==='running';$('#commandText').textContent=selecting?'月震已发生，7 秒内完成最后选择。':race.status==='ready'?'两条路线，一个目的地。':race.paused?'定位恢复后，可从当前状态继续。':race.status==='finished'?'本次撤离结束，准备下一轮。':'观察对手，把握唯一一次落石。';$('#headline').textContent=selecting?'月面正在改变。':race.status==='finished'?'撤离行动结束。':'月面最后一程。';
 if(race.status==='finished'){const r=$('#result');r.hidden=false;r.innerHTML=`<span class="eyebrow">EVACUATION COMPLETE</span><h2 style="color:${race.winner==='tie'?'#e7cb8d':colors[race.winner]}">${race.winner==='tie'?'双车并列撤离成功':race.winner===0?'蓝方撤离成功':'黄方撤离成功'}</h2><p>以车辆实际进入停靠区为准 · 任务用时 ${race.firstArrival.toFixed(1)} 秒</p><table><tr><th>任务记录</th><th>蓝方</th><th>黄方</th></tr>${[['行驶路线',...race.players.map(p=>routeName[p.opening]+' → '+routeName[p.final])],['信标 / 舱门',...race.players.map(p=>p.beacon?'已触发 / 已通过':'未使用')],['落石 / 绕行',...race.players.map(p=>(p.card?'未出牌':'已出牌')+' / '+p.detours.length+' 次')],['抵达状态',...race.players.map(p=>p.arrived!==null?p.arrived.toFixed(1)+' 秒':'未抵达')]].map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')}</table><p>余震：${race.aftershock===null?'未触发':race.aftershock==='stable'?'道路稳定':'前方塌陷'}</p><button class="primary" data-reset>再来一局 ↻</button>`;}else $('#result').hidden=true;
 }
 const event=race.events[0];if(event.text!==lastEvent){lastEvent=event.text;eventAt=performance.now();$('#log').textContent=`${event.time.toFixed(1)}s · ${event.text}`;$('#eventBanner').textContent=event.text;beep();}$('#eventBanner').classList.toggle('visible',race.status==='running'&&performance.now()-eventAt<4000);
}
function reset(){race.reset();world.resetEffects();demo=false;uiLast='';render();renderUI();}
function choose(id,route){if(race.status==='ready')race.chooseOpening(id,route);else race.chooseFinal(id,route);renderUI();}
function attack(id){if(!race.attack(id)){ $('#log').textContent='暂无安全的合法落点，卡牌未消耗。';}renderUI();}
function openDualScreen(){window.open('sandbox.html','moonfall-hardware-console');}
$('#fxBtn').onclick=()=>world.preview();
$('#quakeBtn').onclick=()=>world.previewQuake();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>world.setView(b.dataset.view));
$('#startBtn').onclick=()=>{if(world.loaded)race.start();renderUI();};$('#demoBtn').onclick=()=>{if(!world.loaded)return;reset();demo=true;race.chooseOpening(0,'beacon');race.chooseOpening(1,'outer');race.start();renderUI();};$('#resetBtn').onclick=reset;$('#pauseBtn').onclick=()=>{race.paused=!race.paused;renderUI();};$('#floorBtn').onclick=()=>{openDualScreen();};canvas.ondblclick=()=>document.body.classList.remove('floor');$('#helpBtn').onclick=()=>$('#help').showModal();$('#closeHelp').onclick=$('#gotIt').onclick=()=>$('#help').close();$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent='声音：'+(sound?'开':'关');$('#soundBtn').setAttribute('aria-pressed',String(sound));beep();};
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]'),a=e.target.closest('[data-attack]');if(r&&!r.disabled)choose(+r.dataset.player,r.dataset.route);if(a&&!a.disabled)attack(+a.dataset.attack);if(e.target.closest('[data-reset]'))reset();});
document.addEventListener('keydown',e=>{if(e.repeat||$('#help').open||['INPUT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase(),options=race.quake!==null?['risk','safe']:['beacon','outer'];if(['1','2'].includes(k))choose(0,options[+k-1]);if(['8','9'].includes(k))choose(1,options[+k-8]);if(k==='q')attack(0);if(k==='p')attack(1);if(k===' '&&race.status==='running'){e.preventDefault();race.paused=!race.paused;renderUI();}if(k==='f')openDualScreen();if(k==='escape')document.body.classList.remove('floor');});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;
 if(!qa&&world.loaded){if(demo&&race.status==='running'&&!race.paused){if(race.time>9&&race.players[1].card)race.attack(1);if(race.quake!==null&&!race.locked&&race.time-race.quake>2){race.chooseFinal(0,'risk');race.chooseFinal(1,'safe');}if(race.locked&&race.time-race.quake>4&&race.players[0].card)race.attack(0);}race.step(dt);}
 render();renderUI();requestAnimationFrame(frame);
}renderUI();requestAnimationFrame(frame);
// Deterministic engineering clock only behind explicit QA flag; never changes position directly.
if(qa)window.lunarTest={advance(seconds){if(!world.loaded)throw Error('Scene not ready');if(!Number.isFinite(seconds)||seconds<0||seconds>120)throw Error('Invalid test interval');race.step(seconds);render();renderUI();return JSON.parse(JSON.stringify(race));}};
// Explicit, read-only inspection surface for integration smoke tests.
window.lunar={world:()=>world.diagnostics(),snapshot:()=>JSON.parse(JSON.stringify(race)),getRouteTimings:()=>({beacon:42,outer:48,safe:20,risk:(ROUTES.riskIn.length+ROUTES.riskRock.length+ROUTES.source.length+ROUTES.stable.length)/SPEED,collapse:(ROUTES.riskIn.length+ROUTES.riskRock.length+ROUTES.source.length+ROUTES.collapse.length)/SPEED})};

}
